// PayPal sandbox integration.
// Orders + Payments go through the official TypeScript Server SDK (@paypal/paypal-server-sdk, generated by APIMatic).
// Webhook signature verification and webhook registration are not in the SDK, so they use fetch.
// Every call returns a `trace` (method, endpoint, HTTP status, PayPal status, debug_id, latency; ids masked) that the
// domain writes to the public ledger. Failed calls carry the same trace on the thrown error (see `classify`).
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  LogLevel,
  OrdersController,
  PaymentsController,
  PaypalExperienceLandingPage,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
  ShipmentCarrier,
} from "@paypal/paypal-server-sdk";
import type { ApiResponse } from "@paypal/paypal-server-sdk";
import { PAYPAL_API_BASE, env } from "./env";
import { fromPayPal, toPayPal } from "../shared/money";
import { maskId, maskKey, type Trace } from "./trace";

const client = new Client({
  clientCredentialsAuthCredentials: {
    oAuthClientId: env.PAYPAL_CLIENT_ID,
    oAuthClientSecret: env.PAYPAL_CLIENT_SECRET,
  },
  environment: Environment.Sandbox, // sandbox only, by design
  timeout: 30_000,
  httpClientOptions: { retryConfig: { maxNumberOfRetries: 0 } }, // retries are owned by our persistent queue
  // SDK request logging stays OFF (it would print every call); set PAYPAL_SDK_LOG=1 to debug, with headers masked and no bodies.
  ...(process.env.PAYPAL_SDK_LOG === "1"
    ? { logging: { logLevel: LogLevel.Info, maskSensitiveHeaders: true, logRequest: { logBody: false, logHeaders: false }, logResponse: { logBody: false, logHeaders: false } } }
    : {}),
});
const orders = new OrdersController(client);
const payments = new PaymentsController(client);

// ---------- error classification ----------

export type ErrorClass = "RETRYABLE" | "TERMINAL" | "CONFIG" | "WAIT";

export interface PayPalFailure {
  status: number;
  issue: string;
  description: string;
  debugId?: string;
  retryAfterMs?: number;
  cls: ErrorClass;
  /** trace of the failed call, when the failure came from a traced PayPal call */
  trace?: Trace;
}

function header(headers: unknown, name: string): string | undefined {
  if (!headers || typeof headers !== "object") return undefined;
  const hit = Object.entries(headers as Record<string, unknown>).find(([k]) => k.toLowerCase() === name);
  return hit ? String(hit[1]) : undefined;
}

/** Error taxonomy follows the APIMatic Context Plugin skill `paypal:typescript-error-handling`. */
export function classify(e: unknown): PayPalFailure {
  const trace = (e as { paypalTrace?: Trace } | null)?.paypalTrace;
  if (e instanceof ApiError) {
    type PayPalErrorBody = { name?: string; message?: string; debug_id?: string; details?: { issue?: string; description?: string }[] };
    let body = (e as unknown as { result?: PayPalErrorBody }).result;
    if (!body && typeof e.body === "string") {
      try {
        body = JSON.parse(e.body) as PayPalErrorBody;
      } catch {
        body = { message: e.body.slice(0, 200) };
      }
    }
    const issue = body?.details?.[0]?.issue ?? body?.name ?? "UNKNOWN";
    const description = body?.details?.[0]?.description ?? body?.message ?? "";
    const status = e.statusCode;
    const retryAfter = Number(header(e.headers, "retry-after"));
    let cls: ErrorClass = "TERMINAL";
    if (status === 429 || status >= 500) cls = "RETRYABLE";
    else if (status === 401 || status === 403) cls = "CONFIG";
    else if (issue === "ORDER_NOT_APPROVED") cls = "WAIT";
    return {
      status,
      issue,
      description,
      debugId: body?.debug_id ?? header(e.headers, "paypal-debug-id"),
      retryAfterMs: Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : undefined,
      cls,
      trace,
    };
  }
  const err = e instanceof Error ? e : new Error(String(e));
  const code = (err as Error & { code?: string }).code ?? "";
  if (err.name === "AbortError" || err.name === "TimeoutError" || /^(ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|ECONNRESET|ERR_NETWORK)/.test(code) || /network|socket|timeout/i.test(err.message)) {
    return { status: 0, issue: "NETWORK", description: err.message, cls: "RETRYABLE", trace };
  }
  if (err.message.startsWith("Required authentication credentials")) return { status: 0, issue: "CREDENTIALS", description: err.message, cls: "CONFIG", trace };
  return { status: 0, issue: err.name || "ERROR", description: err.message, cls: "TERMINAL", trace };
}

/** Per-call deadline (the SDK timeout is per attempt and does not cover the token fetch). */
const deadline = () => ({ abortSignal: AbortSignal.timeout(45_000) });

/** Runs one SDK call and records its trace. On failure the trace is attached to the error (`paypalTrace`). */
async function traced<T>(
  base: { method: string; endpoint: string; id?: string; requestId?: string },
  call: () => Promise<ApiResponse<T>>,
  statusOf: (r: T) => string | undefined,
): Promise<{ result: T; trace: Trace }> {
  const t0 = Date.now();
  const trace: Trace = { method: base.method, endpoint: base.endpoint, id: maskId(base.id), requestId: maskKey(base.requestId) };
  try {
    const res = await call();
    trace.ms = Date.now() - t0;
    trace.httpStatus = res.statusCode;
    trace.paypalStatus = statusOf(res.result) || undefined;
    trace.debugId = header(res.headers, "paypal-debug-id");
    return { result: res.result, trace };
  } catch (e) {
    trace.ms = Date.now() - t0;
    if (e && typeof e === "object") {
      const f = classify(e);
      trace.httpStatus = f.status || undefined;
      trace.paypalStatus = f.issue;
      trace.debugId = f.debugId;
      (e as { paypalTrace?: Trace }).paypalTrace = trace;
    }
    throw e;
  }
}

/** Builds the value of the PayPal-Mock-Response header (sandbox negative testing). */
export function mockHeader(code: string | undefined): string | undefined {
  return code ? JSON.stringify({ mock_application_codes: code }) : undefined;
}

// ---------- orders ----------

export interface CreateHoldInput {
  dropId: string;
  entryId: string;
  /** custom_id: public entry id + seed commitment, kept in PayPal's own record of the hold */
  binding: string;
  title: string;
  sku: string;
  priceCents: number;
  shipHoldCents: number;
  returnUrl: string;
  cancelUrl: string;
}

export async function createHoldOrder(i: CreateHoldInput): Promise<{ orderId: string; approveUrl?: string; trace: Trace }> {
  const total = i.priceCents + i.shipHoldCents;
  const requestId = `create:${i.entryId}`;
  const { result, trace } = await traced(
    { method: "POST", endpoint: "/v2/checkout/orders", requestId },
    () =>
      orders.createOrder(
        {
          paypalRequestId: requestId,
          prefer: "return=representation",
          body: {
            intent: CheckoutPaymentIntent.Authorize,
            purchaseUnits: [
              {
                referenceId: i.dropId,
                customId: i.binding,
                description: `Paylet allocation ballot — right to purchase "${i.title}" at list price`,
                softDescriptor: "PAYLET",
                amount: {
                  currencyCode: "USD",
                  value: toPayPal(total),
                  breakdown: {
                    itemTotal: { currencyCode: "USD", value: toPayPal(i.priceCents) },
                    shipping: { currencyCode: "USD", value: toPayPal(i.shipHoldCents) },
                  },
                },
                items: [{ name: i.title.slice(0, 127), quantity: "1", sku: i.sku, unitAmount: { currencyCode: "USD", value: toPayPal(i.priceCents) } }],
              },
            ],
            paymentSource: {
              paypal: {
                experienceContext: {
                  brandName: "Paylet",
                  locale: "en-US",
                  shippingPreference: PaypalWalletContextShippingPreference.GetFromFile,
                  userAction: PaypalExperienceUserAction.Continue,
                  landingPage: PaypalExperienceLandingPage.Login,
                  returnUrl: i.returnUrl,
                  cancelUrl: i.cancelUrl,
                },
              },
            },
          },
        },
        deadline(),
      ),
    (o) => (o.status ? String(o.status) : undefined),
  );
  if (!result.id) throw new Error("createOrder: PayPal returned no order id");
  trace.id = maskId(result.id);
  const approveUrl = result.links?.find((l) => l.rel === "payer-action")?.href ?? result.links?.find((l) => l.rel === "approve")?.href;
  return { orderId: result.id, approveUrl, trace };
}

export interface OrderIdentity {
  status: string;
  payerId?: string;
  accountId?: string;
  /** PayPal wallet account status: VERIFIED | UNVERIFIED (KYA-lite, P2-16) */
  accountStatus?: string;
  email?: string;
  name?: string;
  address?: { line1: string; line2?: string; city?: string; state?: string; zip?: string; country?: string };
  trace?: Trace;
}

/** Server-side only: identity fields never leave the backend in clear. */
export async function getOrderIdentity(orderId: string): Promise<OrderIdentity> {
  const { result: o, trace } = await traced(
    { method: "GET", endpoint: `/v2/checkout/orders/${maskId(orderId)}`, id: orderId },
    () => orders.getOrder({ id: orderId }, deadline()),
    (r) => (r.status ? String(r.status) : undefined),
  );
  const pp = o.paymentSource?.paypal;
  const ship = o.purchaseUnits?.[0]?.shipping;
  const a = ship?.address;
  const nm = o.payer?.name;
  return {
    status: String(o.status ?? ""),
    payerId: o.payer?.payerId,
    accountId: pp?.accountId,
    accountStatus: pp?.accountStatus ? String(pp.accountStatus) : undefined,
    email: o.payer?.emailAddress ?? pp?.emailAddress,
    name: ship?.name?.fullName ?? [nm?.givenName, nm?.surname].filter(Boolean).join(" "),
    address: a
      ? { line1: a.addressLine1 ?? "", line2: a.addressLine2, city: a.adminArea2, state: a.adminArea1, zip: a.postalCode, country: a.countryCode }
      : undefined,
    trace,
  };
}

export async function authorizeOrder(orderId: string, requestId: string, opts: { mock?: string } = {}) {
  const { result, trace } = await traced(
    { method: "POST", endpoint: `/v2/checkout/orders/${maskId(orderId)}/authorize`, id: orderId, requestId },
    () => orders.authorizeOrder({ id: orderId, paypalRequestId: requestId, prefer: "return=representation", paypalMockResponse: mockHeader(opts.mock) }, deadline()),
    (r) => {
      const a = r.purchaseUnits?.[0]?.payments?.authorizations?.[0];
      return a?.status ? String(a.status) : r.status ? String(r.status) : undefined;
    },
  );
  const auth = result.purchaseUnits?.[0]?.payments?.authorizations?.[0];
  if (auth?.id) trace.id = maskId(auth.id);
  return { authorizationId: auth?.id, status: String(auth?.status ?? ""), amount: auth?.amount?.value, expiresAt: auth?.expirationTime, trace };
}

/** Order + its trackers (used to make tracking idempotent: PayPal's /track takes no PayPal-Request-Id). */
async function getOrderTrackers(orderId: string): Promise<string[]> {
  const { result } = await orders.getOrder({ id: orderId }, deadline());
  return (result.purchaseUnits ?? []).flatMap((u) => (u.shipping?.trackers ?? []).map((t) => t.id ?? "")).filter(Boolean);
}

export const CARRIERS = { USPS: ShipmentCarrier.Usps, UPS: ShipmentCarrier.Ups, FEDEX: ShipmentCarrier.Fedex, OTHER: ShipmentCarrier.Other } as const;
export type CarrierCode = keyof typeof CARRIERS;

/** Adds shipment tracking to the order (POST /v2/checkout/orders/{id}/track); PayPal shows it to the buyer and
 *  notifies them. Idempotent: PayPal names trackers `${captureId}-${trackingNumber}`, so an existing one is reused. */
export async function addTracking(orderId: string, captureId: string, trackingNumber: string, carrier: CarrierCode) {
  const trackerId = `${captureId}-${trackingNumber}`;
  const existing = await getOrderTrackers(orderId).catch(() => [] as string[]);
  const endpoint = `/v2/checkout/orders/${maskId(orderId)}/track`;
  if (existing.includes(trackerId)) {
    return { trackerId, already: true, trace: { method: "POST", endpoint, id: maskId(captureId), paypalStatus: "ALREADY_TRACKED", requestId: maskKey(`track:${captureId}`) } as Trace };
  }
  const { trace } = await traced(
    { method: "POST", endpoint, id: captureId, requestId: `track:${captureId}` },
    () =>
      orders.createOrderTracking(
        {
          id: orderId,
          body: {
            captureId,
            trackingNumber,
            carrier: CARRIERS[carrier],
            ...(carrier === "OTHER" ? { carrierNameOther: "Other" } : {}),
            notifyPayer: true,
          },
        },
        deadline(),
      ),
    (r) => {
      const t = (r.purchaseUnits ?? []).flatMap((u) => u.shipping?.trackers ?? []).find((x) => x.id === trackerId);
      return t?.status ? String(t.status) : r.status ? String(r.status) : undefined;
    },
  );
  return { trackerId, already: false, trace };
}

// ---------- payments ----------

export async function getAuthorization(authorizationId: string) {
  const { result, trace } = await traced(
    { method: "GET", endpoint: `/v2/payments/authorizations/${maskId(authorizationId)}`, id: authorizationId },
    () => payments.getAuthorizedPayment({ authorizationId }, deadline()),
    (r) => (r.status ? String(r.status) : undefined),
  );
  return { status: String(result.status ?? ""), amount: result.amount?.value, customId: result.customId, createdAt: result.createTime, trace };
}

/** The authorization PayPal holds for an order, if any: a timed-out /authorize may have landed all the same. */
export async function findAuthorization(orderId: string): Promise<string | null> {
  const { result } = await orders.getOrder({ id: orderId }, deadline());
  return result.purchaseUnits?.[0]?.payments?.authorizations?.[0]?.id ?? null;
}

/** The capture PayPal holds for an order, if any (a capture may land after we gave up waiting for its answer). */
export async function findCapture(orderId: string): Promise<{ captureId: string; amountCents: number } | null> {
  const { result } = await orders.getOrder({ id: orderId }, deadline());
  const c = result.purchaseUnits?.[0]?.payments?.captures?.[0];
  return c?.id ? { captureId: c.id, amountCents: fromPayPal(c.amount?.value) } : null;
}

export async function captureAuthorization(authorizationId: string, amountCents: number, requestId: string, invoiceId: string, opts: { mock?: string } = {}) {
  const { result, trace } = await traced(
    { method: "POST", endpoint: `/v2/payments/authorizations/${maskId(authorizationId)}/capture`, id: authorizationId, requestId },
    () =>
      payments.captureAuthorizedPayment(
        {
          authorizationId,
          paypalRequestId: requestId,
          paypalMockResponse: mockHeader(opts.mock),
          prefer: "return=representation",
          body: {
            amount: { currencyCode: "USD", value: toPayPal(amountCents) },
            finalCapture: true,
            invoiceId,
            noteToPayer: "Your Paylet allocation — thanks for buying direct from the maker.",
            softDescriptor: "PAYLET",
          },
        },
        deadline(),
      ),
    (r) => (r.status ? String(r.status) : undefined),
  );
  if (result.id) trace.id = maskId(result.id);
  return { captureId: result.id, status: String(result.status ?? ""), amount: result.amount?.value, trace };
}

/** GET /v2/payments/captures/{id}: the source of truth for PENDING captures and refunds. */
export async function getCapture(captureId: string) {
  const { result, trace } = await traced(
    { method: "GET", endpoint: `/v2/payments/captures/${maskId(captureId)}`, id: captureId },
    () => payments.getCapturedPayment({ captureId }, deadline()),
    (r) => (r.status ? String(r.status) : undefined),
  );
  return { status: String(result.status ?? ""), amountCents: fromPayPal(result.amount?.value), reason: result.statusDetails?.reason ? String(result.statusDetails.reason) : undefined, trace };
}

/** Full refund of a capture (empty amount = everything that was captured). Idempotent through PayPal-Request-Id. */
export async function refundCapture(captureId: string, requestId: string, noteToPayer: string) {
  const { result, trace } = await traced(
    { method: "POST", endpoint: `/v2/payments/captures/${maskId(captureId)}/refund`, id: captureId, requestId },
    () =>
      payments.refundCapturedPayment(
        { captureId, paypalRequestId: requestId, prefer: "return=representation", body: { noteToPayer: noteToPayer.slice(0, 255) } },
        deadline(),
      ),
    (r) => (r.status ? String(r.status) : undefined),
  );
  if (result.id) trace.id = maskId(result.id);
  return { refundId: result.id, status: String(result.status ?? ""), amountCents: fromPayPal(result.amount?.value), trace };
}

/** Void is not idempotent on PayPal's side: GET first, treat PREVIOUSLY_VOIDED as success. */
export async function voidAuthorizationSafe(authorizationId: string, requestId: string): Promise<{ status: string; already?: boolean; trace?: Trace }> {
  const current = await getAuthorization(authorizationId);
  if (current.status === "VOIDED") return { status: "VOIDED", already: true, trace: current.trace };
  if (current.status === "CAPTURED" || current.status === "PARTIALLY_CAPTURED") return { status: current.status, already: true, trace: current.trace };
  try {
    const { trace } = await traced(
      { method: "POST", endpoint: `/v2/payments/authorizations/${maskId(authorizationId)}/void`, id: authorizationId, requestId },
      () => payments.voidPayment({ authorizationId, paypalRequestId: requestId, prefer: "return=minimal" }, deadline()),
      () => "VOIDED",
    );
    return { status: "VOIDED", trace };
  } catch (e) {
    const f = classify(e);
    if (f.issue === "PREVIOUSLY_VOIDED" || f.issue === "AUTHORIZATION_VOIDED") return { status: "VOIDED", already: true, trace: f.trace };
    throw e;
  }
}

// ---------- raw REST (webhooks) ----------

let token: { value: string; exp: number } | undefined;
let inflight: Promise<string> | undefined;
async function accessToken(): Promise<string> {
  if (token && token.exp > Date.now() + 60_000) return token.value;
  inflight ??= fetchToken().finally(() => (inflight = undefined));
  return inflight;
}
async function fetchToken(): Promise<string> {
  const res = await fetch(`${PAYPAL_API_BASE}/v1/oauth2/token`, {
    method: "POST",
    headers: {
      Authorization: `Basic ${Buffer.from(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_CLIENT_SECRET}`).toString("base64")}`,
      "Content-Type": "application/x-www-form-urlencoded",
    },
    body: "grant_type=client_credentials",
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`oauth ${res.status} debug_id=${res.headers.get("paypal-debug-id") ?? "-"}`);
  const j = (await res.json()) as { access_token: string; expires_in: number };
  token = { value: j.access_token, exp: Date.now() + j.expires_in * 1000 };
  return token.value;
}

async function rest<T>(method: string, path: string, body?: unknown): Promise<{ status: number; json: T }> {
  const res = await fetch(`${PAYPAL_API_BASE}${path}`, {
    method,
    headers: { Authorization: `Bearer ${await accessToken()}`, "Content-Type": "application/json" },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: AbortSignal.timeout(20_000),
  });
  const text = await res.text();
  if (res.status >= 400) throw new Error(`PayPal ${method} ${path} → ${res.status} debug_id=${res.headers.get("paypal-debug-id") ?? "-"} ${text.slice(0, 160)}`);
  return { status: res.status, json: (text ? JSON.parse(text) : {}) as T };
}

export interface WebhookVerification {
  verified: boolean;
  httpStatus?: number;
  debugId?: string;
  ms: number;
}

/** POST /v1/notifications/verify-webhook-signature with the raw body, byte for byte. */
export async function verifyWebhookSignature(headers: Headers, rawBody: string, webhookId: string): Promise<WebhookVerification> {
  const t0 = Date.now();
  const h = (k: string) => headers.get(k) ?? "";
  if (!h("paypal-transmission-id") || !webhookId) return { verified: false, ms: 0 };
  // PayPal requires the original event object; splice the raw body in without re-serialising it.
  const payload = `{"auth_algo":${JSON.stringify(h("paypal-auth-algo"))},"cert_url":${JSON.stringify(h("paypal-cert-url"))},"transmission_id":${JSON.stringify(
    h("paypal-transmission-id"),
  )},"transmission_sig":${JSON.stringify(h("paypal-transmission-sig"))},"transmission_time":${JSON.stringify(
    h("paypal-transmission-time"),
  )},"webhook_id":${JSON.stringify(webhookId)},"webhook_event":${rawBody}}`;
  const res = await fetch(`${PAYPAL_API_BASE}/v1/notifications/verify-webhook-signature`, {
    method: "POST",
    headers: { Authorization: `Bearer ${await accessToken()}`, "Content-Type": "application/json" },
    body: payload,
    signal: AbortSignal.timeout(20_000),
  });
  const debugId = res.headers.get("paypal-debug-id") ?? undefined;
  if (!res.ok) return { verified: false, httpStatus: res.status, debugId, ms: Date.now() - t0 };
  const j = (await res.json()) as { verification_status?: string };
  return { verified: j.verification_status === "SUCCESS", httpStatus: res.status, debugId, ms: Date.now() - t0 };
}

export const WEBHOOK_EVENTS = [
  "CHECKOUT.ORDER.APPROVED",
  "PAYMENT.AUTHORIZATION.CREATED",
  "PAYMENT.AUTHORIZATION.VOIDED",
  "PAYMENT.CAPTURE.COMPLETED",
  "PAYMENT.CAPTURE.PENDING",
  "PAYMENT.CAPTURE.DENIED",
  "PAYMENT.CAPTURE.REFUNDED",
  "PAYMENT.CAPTURE.REVERSED",
  "CUSTOMER.DISPUTE.CREATED",
];

/** Finds or creates the webhook for `${PUBLIC_URL}/webhooks/paypal` and makes sure it subscribes to every event in
 *  WEBHOOK_EVENTS (PATCH /v1/notifications/webhooks/{id} when an older registration lacks some). Returns its id, or ""
 *  if not possible (e.g. localhost). */
export async function ensureWebhook(publicUrl: string): Promise<{ id: string; patched: string[] }> {
  if (!publicUrl.startsWith("https://")) return { id: "", patched: [] };
  const url = `${publicUrl.replace(/\/$/, "")}/webhooks/paypal`;
  const list = await rest<{ webhooks?: { id: string; url: string; event_types?: { name: string }[] }[] }>("GET", "/v1/notifications/webhooks");
  const existing = list.json.webhooks?.find((w) => w.url === url);
  if (existing) {
    const have = new Set((existing.event_types ?? []).map((e) => e.name));
    const missing = have.has("*") ? [] : WEBHOOK_EVENTS.filter((n) => !have.has(n));
    if (missing.length) {
      const all = [...new Set([...have, ...WEBHOOK_EVENTS])];
      try {
        await rest("PATCH", `/v1/notifications/webhooks/${existing.id}`, [{ op: "replace", path: "/event_types", value: all.map((name) => ({ name })) }]);
      } catch (e) {
        // best-effort: keep the existing registration (and its id, which signature verification needs)
        console.warn("[paylet] could not add webhook events:", String(e).slice(0, 160));
        return { id: existing.id, patched: [] };
      }
    }
    return { id: existing.id, patched: missing };
  }
  const created = await rest<{ id?: string }>("POST", "/v1/notifications/webhooks", {
    url,
    event_types: WEBHOOK_EVENTS.map((name) => ({ name })),
  });
  return { id: created.json.id ?? "", patched: [] };
}
